#!/usr/bin/env node
// Builds src/core/generated/assets.js, which bundles two things the converter needs
// in both Node and the browser:
//   1. A compact Firefox-support table distilled from @mdn/browser-compat-data (BCD).
//   2. The source code of every shim in src/shims/, as strings.
// Run automatically by `npm test` and `npm run build`. Never edit the generated file by hand.
import { mkdirSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { createRequire } from "node:module";

const require = createRequire(import.meta.url);
const bcd = require("@mdn/browser-compat-data");
const root = join(dirname(fileURLToPath(import.meta.url)), "..");

/** Returns the Firefox version string that added a feature, or null if unsupported. */
function firefoxVersion(compat) {
  let entry = compat?.support?.firefox;
  if (!entry) return null;
  if (Array.isArray(entry)) entry = entry.find((e) => !e.flags && !e.prefix && !e.alternative_name) ?? null;
  if (!entry || entry.flags || entry.version_removed) return null;
  const v = entry.version_added;
  if (typeof v !== "string" || v === "preview") return null;
  return v.replace(/^≤/, "");
}

const children = (node) => Object.keys(node).filter((k) => k !== "__compat");
const w = bcd.webextensions;

const manifestKeys = {};
const manifestSubKeys = {};
for (const key of children(w.manifest)) {
  manifestKeys[key] = firefoxVersion(w.manifest[key].__compat);
  for (const sub of children(w.manifest[key])) {
    manifestSubKeys[`${key}.${sub}`] = firefoxVersion(w.manifest[key][sub].__compat);
  }
}

const permissions = {};
for (const perm of children(w.manifest.permissions)) {
  permissions[perm] = firefoxVersion(w.manifest.permissions[perm].__compat);
}

const apis = {};
for (const ns of children(w.api)) {
  const members = {};
  for (const m of children(w.api[ns])) members[m] = firefoxVersion(w.api[ns][m].__compat);
  apis[ns] = { __ns: firefoxVersion(w.api[ns].__compat), ...members };
}

const shimDir = join(root, "src", "shims");
const shims = {};
for (const file of readdirSync(shimDir).sort()) {
  if (file.endsWith(".js") || file.endsWith(".html")) shims[file] = readFileSync(join(shimDir, file), "utf8");
}

const out = `// GENERATED by scripts/build-assets.js — do not edit.
// BCD version: ${bcd.__meta.version}
export const support = ${JSON.stringify({ bcdVersion: bcd.__meta.version, manifestKeys, manifestSubKeys, permissions, apis })};
export const shims = ${JSON.stringify(shims)};
`;
mkdirSync(join(root, "src", "core", "generated"), { recursive: true }); // git-ignored, so absent after a fresh clone
writeFileSync(join(root, "src", "core", "generated", "assets.js"), out);
console.log(`assets.js written (BCD ${bcd.__meta.version}, ${Object.keys(shims).length} shim files)`);
